#!/usr/bin/env python3
"""Rasterise DejaVu Sans into src/spek-font.h for spek-cli's image header.

spek-cli writes PNGs without a display, so it can't ask the system to draw
text. This bakes anti-aliased glyphs (ASCII and Latin-1) into a header.
DejaVu fonts are under the Bitstream Vera licence, which permits this.

Usage: python3 dist/font/make-font.py /path/to/DejaVuSans.ttf /path/to/DejaVuSans-Bold.ttf > src/spek-font.h
"""
import sys
from PIL import Image, ImageDraw, ImageFont

CODEPOINTS = list(range(32, 127)) + list(range(160, 256)) + [0x2013, 0x2014, 0x2019, 0x201C, 0x201D, 0x2026, 0x2713, 0x2717]


def bake(path, size, name, out):
    font = ImageFont.truetype(path, size)
    ascent, descent = font.getmetrics()
    height = ascent + descent
    glyphs, data = [], []
    for cp in CODEPOINTS:
        ch = chr(cp)
        adv = max(1, round(font.getlength(ch)))
        img = Image.new("L", (adv + 4, height), 0)
        ImageDraw.Draw(img).text((0, 0), ch, font=font, fill=255)
        # keep the full cell, trimmed of empty columns to the right of the advance
        w = adv
        bbox = img.getbbox()
        if bbox:
            w = max(w, bbox[2])
        px = img.crop((0, 0, w, height)).tobytes()
        glyphs.append((cp, adv, w, len(data)))
        data.extend(px)
    out.append(f"static const unsigned char {name}_alpha[] = {{")
    for i in range(0, len(data), 24):
        out.append("    " + ",".join(str(b) for b in data[i:i + 24]) + ",")
    out.append("};")
    out.append(f"static const SpekGlyph {name}_glyphs[] = {{")
    for cp, adv, w, off in glyphs:
        out.append(f"    {{ 0x{cp:04x}, {adv}, {w}, {off} }},")
    out.append("};")
    out.append(f"static const SpekFont {name} = {{ {height}, {ascent}, {len(glyphs)}, {name}_glyphs, {name}_alpha }};")


def main():
    regular, bold = sys.argv[1], sys.argv[2]
    out = [
        "// Generated by dist/font/make-font.py from DejaVu Sans. Don't edit.",
        "// DejaVu fonts: Bitstream Vera licence, see https://dejavu-fonts.github.io/License.html",
        "#pragma once",
        "",
        "struct SpekGlyph { unsigned int cp; int advance; int width; unsigned int offset; };",
        "struct SpekFont { int height; int ascent; int count; const SpekGlyph *glyphs; const unsigned char *alpha; };",
        "",
    ]
    bake(bold, 17, "spek_font_title", out)
    bake(regular, 13, "spek_font_body", out)
    bake(bold, 13, "spek_font_body_bold", out)
    print("\n".join(out))


if __name__ == "__main__":
    main()
